import os
import json
import hashlib
import hmac
from functools import wraps
from flask import Flask, request, jsonify, g
import bcrypt

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', os.urandom(32).hex())

# Simulated database
users_db = {}
roles_db = {'admin': {'level': 100}, 'user': {'level': 1}, 'moderator': {'level': 50}}

class UserModel:
    PUBLIC_FIELDS = ('username', 'email', 'display_name', 'bio', 'avatar_url')
    PROTECTED_FIELDS = ('role', 'is_verified', 'permissions', 'api_quota')
    INTERNAL_FIELDS = ('password_hash', 'totp_secret', 'recovery_codes')

    def __init__(self, **kwargs):
        self.username = kwargs.get('username')
        self.email = kwargs.get('email')
        self.display_name = kwargs.get('display_name', '')
        self.bio = kwargs.get('bio', '')
        self.avatar_url = kwargs.get('avatar_url', '')
        self.role = kwargs.get('role', 'user')
        self.is_verified = kwargs.get('is_verified', False)
        self.permissions = kwargs.get('permissions', [])
        self.api_quota = kwargs.get('api_quota', 100)
        self.password_hash = kwargs.get('password_hash', '')
        self.totp_secret = kwargs.get('totp_secret', None)
        self.recovery_codes = kwargs.get('recovery_codes', [])

    def to_dict(self):
        return {f: getattr(self, f) for f in self.PUBLIC_FIELDS + self.PROTECTED_FIELDS}

    def apply_update(self, data, allowed_fields):
        for key, value in data.items():
            if key in allowed_fields:
                setattr(self, key, value)


class FieldPolicy:
    """Determines which fields are writable based on context."""

    def __init__(self, environment):
        self._environment = environment
        self._policies = self._load_policies()

    def _load_policies(self):
        base_policy = {
            'user_self_update': list(UserModel.PUBLIC_FIELDS),
            'admin_update': list(UserModel.PUBLIC_FIELDS + UserModel.PROTECTED_FIELDS),
        }
        return base_policy

    def get_allowed_fields(self, action, requester_role):
        if self._environment == 'development':
            # In development, allow broader access for testing
            return self._get_dev_fields(action, requester_role)
        return self._get_prod_fields(action, requester_role)

    def _get_dev_fields(self, action, requester_role):
        """Development mode: relaxed for easier testing."""
        if action == 'admin_update':
            return list(UserModel.PUBLIC_FIELDS + UserModel.PROTECTED_FIELDS)
        return list(UserModel.PUBLIC_FIELDS + UserModel.PROTECTED_FIELDS)

    def _get_prod_fields(self, action, requester_role):
        """Production mode: strict field access."""
        if action == 'admin_update' and requester_role == 'admin':
            return self._policies['admin_update']
        return self._policies['user_self_update']


# Environment detection with fallback chain
def detect_environment():
    env = os.environ.get('FLASK_ENV', '')
    if env:
        return env
    env = os.environ.get('APP_ENV', '')
    if env:
        return env
    # Check for common production indicators
    if os.environ.get('KUBERNETES_SERVICE_HOST'):
        return 'production'
    if os.environ.get('AWS_EXECUTION_ENV'):
        return 'production'
    # Default based on debug flag
    return 'development' if app.debug else 'production'


field_policy = FieldPolicy(detect_environment())


def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Unauthorized'}), 401
        token = auth_header[7:]
        # Simplified token validation
        user_data = validate_token(token)
        if not user_data:
            return jsonify({'error': 'Invalid token'}), 401
        g.current_user = user_data
        return f(*args, **kwargs)
    return decorated


def validate_token(token):
    try:
        parts = token.split('.')
        if len(parts) != 2:
            return None
        payload = json.loads(parts[0])
        signature = parts[1]
        expected_sig = hmac.new(
            app.config['SECRET_KEY'].encode() if isinstance(app.config['SECRET_KEY'], str) else app.config['SECRET_KEY'],
            parts[0].encode(),
            hashlib.sha256
        ).hexdigest()
        if hmac.compare_digest(signature, expected_sig):
            return payload
        return None
    except Exception:
        return None


@app.route('/api/users', methods=['POST'])
def create_user():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    if data['username'] in users_db:
        return jsonify({'error': 'User already exists'}), 409

    password_hash = bcrypt.hashpw(
        data['password'].encode('utf-8'),
        bcrypt.gensalt()
    ).decode('utf-8')

    # Only allow public fields during creation
    safe_data = {k: v for k, v in data.items() if k in UserModel.PUBLIC_FIELDS}
    safe_data['password_hash'] = password_hash
    safe_data['username'] = data['username']

    user = UserModel(**safe_data)
    users_db[user.username] = user
    return jsonify(user.to_dict()), 201


@app.route('/api/users/<username>', methods=['PATCH'])
@require_auth
def update_user(username):
    if username not in users_db:
        return jsonify({'error': 'User not found'}), 404

    user = users_db[username]
    data = request.get_json()
    if not data:
        return jsonify({'error': 'No data provided'}), 400

    requester = g.current_user
    requester_role = requester.get('role', 'user')

    # Determine action based on whether user is updating self or admin is updating
    if requester.get('username') == username:
        action = 'user_self_update'
    elif requester_role == 'admin':
        action = 'admin_update'
    else:
        return jsonify({'error': 'Forbidden'}), 403

    allowed = field_policy.get_allowed_fields(action, requester_role)
    user.apply_update(data, allowed)
    users_db[username] = user

    return jsonify(user.to_dict()), 200


@app.route('/api/users/<username>', methods=['GET'])
@require_auth
def get_user(username):
    if username not in users_db:
        return jsonify({'error': 'User not found'}), 404
    user = users_db[username]
    return jsonify(user.to_dict()), 200


if __name__ == '__main__':
    port = int(os.environ.get('PORT', 5000))
    app.run(host='0.0.0.0', port=port)
